def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    for x in range(1, int(n**(1/3)) + 2):
        for y in range(1, x):
            if x**3 - y**3 == n:
                return (x, y)
    return None

def max_score(grid: List[List[int]]) -> int:
    n = len(grid)
    m = len(grid[0])
    selected = set()
    score = 0
    for i in range(n):
        for j in range(m):
            if j not in selected and all(grid[i][j] != grid[k][l] for k in range(n) for l in range(m) if l not in selected and k != i):
                selected.add(j)
                score += grid[i][j]
                break
    return score
